with parsed as (select id, customer_id, created_at, coupon_codes, items, attributes, size(items) as num_items, coalesce(attributes['utm_source'], 'none') as utm_source_or_default, forall(items, item -> item.qty <= 5) as all_small_qty from carts) select *, sum(num_items) over (partition by customer_id order by created_at, id rows between unbounded preceding and current row) as cumulative_num_items, sum(num_items) over (partition by customer_id order by created_at, id rows between unbounded preceding and current row) as running_num_items, count(num_items) over (partition by customer_id order by cast(created_at as bigint) range between 7200 preceding and current row) as num_items_count_2h from parsed;
